/**
 * A holdout of commercial-classification cases (Task E, 2026-11-24), written
 * before the structural transaction reading was tuned and kept verbatim since.
 * None is a production row: each is a realistic arrangement of the kind Brain
 * harvests, with the fields an opening already carries (payer, offer scope,
 * buying signal, source) and the sentence its price figure rests on.
 *
 * `counts` is whether that figure is evidence of what this arrangement's buyer
 * pays for this deliverable: a purchase from a supplier in Brain's position,
 * including a price evidenced for comparable buyers of the same deliverable.
 * Grants, prizes, wages, payouts, fees a seller or bidder pays, and another
 * supplier's price for another deliverable do not count.
 *
 * Do not edit a case to make the classifier pass. Add new cases instead.
 */
export interface HoldoutCase {
  id: string;
  kind: 'PURCHASE' | 'ESTIMATE' | 'RETAINER' | 'MARKETPLACE' | 'PROCUREMENT' | 'GRANT' | 'PRIZE' | 'BOUNTY' | 'WAGE' | 'TRANSFER' | 'BID_FEE' | 'SELLER_FEE' | 'BROKER_FEE' | 'OTHER_DELIVERABLE';
  title: string;
  payer: string;
  offerScope: string;
  buyingSignal: string | null;
  source: string | null;
  evidence: string;
  counts: boolean;
}

